settings.css:
#snooze-custom-checkout {
  font-family: 'Poppins', -apple-system, BlinkMacSystemFont, sans-serif;
  color: #1F293B;
  line-height: 1.6;
  max-width: 1100px;
  margin: 0 auto;
}

#snooze-custom-checkout .snooze-checkout-hero {
  margin-bottom: 2rem;
}

#snooze-custom-checkout .snooze-checkout-hero h1 {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 2.25rem;
  font-weight: 700;
  color: #1F293B;
  margin-bottom: 1rem;
  line-height: 1.2;
}

#snooze-custom-checkout .snooze-checkout-hero .subheadline {
  font-size: 1.125rem;
  color: #7C8A98;
  margin-bottom: 1.5rem;
}

#snooze-custom-checkout .trial-highlight {
  background: #FFE7EA;
  border-radius: 12px;
  padding: 2rem;
  margin-bottom: 2rem;
  text-align: center;
  border: 2px solid #F43357;
}

#snooze-custom-checkout .trial-highlight h2 {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.75rem;
  font-weight: 700;
  color: #1F293B;
  margin-bottom: 1rem;
}

#snooze-custom-checkout .trial-highlight p {
  color: #1F293B;
  font-size: 1rem;
  line-height: 1.6;
  margin: 0;
}

#snooze-custom-checkout .whats-included {
  margin-bottom: 2rem;
  background: white;
  border-radius: 12px;
  padding: 2rem;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.05);
}

#snooze-custom-checkout .whats-included h2 {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.75rem;
  font-weight: 700;
  color: #1F293B;
  margin-bottom: 1.25rem;
}

#snooze-custom-checkout .benefits-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

#snooze-custom-checkout .benefits-list li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.875rem 0;
  border-bottom: 1px solid #F2EDEA;
}

#snooze-custom-checkout .benefits-list li:last-child {
  border-bottom: none;
}

#snooze-custom-checkout .benefits-list .check-icon {
  color: #F43357;
  font-size: 1.25rem;
  flex-shrink: 0;
  margin-top: 0.125rem;
  font-weight: bold;
}

#snooze-custom-checkout .benefits-list .benefit-text {
  flex: 1;
  color: #1F293B;
  font-size: 0.95rem;
}

#snooze-custom-checkout .benefits-list .benefit-detail {
  color: #7C8A98;
  font-size: 0.875rem;
  margin-top: 0.25rem;
}

#snooze-custom-checkout .how-it-works {
  margin-bottom: 2rem;
  background: white;
  border-radius: 12px;
  padding: 2rem;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.05);
}

#snooze-custom-checkout .how-it-works h2 {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.75rem;
  font-weight: 700;
  color: #1F293B;
  margin-bottom: 1.5rem;
  text-align: center;
}

#snooze-custom-checkout .steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-bottom: 1.5rem;
}

#snooze-custom-checkout .step {
  text-align: center;
}

#snooze-custom-checkout .step-number {
  width: 3rem;
  height: 3rem;
  background: #F43357;
  color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0 auto 1rem;
  font-family: 'Playfair Display', Georgia, serif;
}

#snooze-custom-checkout .step-content h3 {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: #1F293B;
  margin-bottom: 0.5rem;
}

#snooze-custom-checkout .step-content p {
  color: #7C8A98;
  font-size: 0.95rem;
  line-height: 1.5;
  margin: 0;
}

#snooze-custom-checkout .why-join {
  background: #FFE7EA;
  border-radius: 12px;
  padding: 1.5rem;
  margin-bottom: 2rem;
}

#snooze-custom-checkout .why-join h2 {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.75rem;
  font-weight: 700;
  color: #1F293B;
  margin-bottom: 1.25rem;
}

#snooze-custom-checkout .why-join p {
  color: #1F293B;
  font-size: 0.95rem;
  line-height: 1.6;
  margin-bottom: 1rem;
}

#snooze-custom-checkout .why-join p:last-child {
  margin-bottom: 0;
}

#snooze-custom-checkout .checkout-footer-note {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid #E5E7EB;
  font-size: 0.875rem;
  color: #7C8A98;
  line-height: 1.6;
}

#snooze-custom-checkout .checkout-footer-note a {
  color: #F43357;
  text-decoration: underline;
}

#snooze-custom-checkout .checkout-currency-link {
  font-size: 0.875rem;
  color: #7C8A98;
}

#snooze-custom-checkout .checkout-currency-link a {
  color: #F43357;
  text-decoration: underline;
}

#snooze-custom-checkout .mobile-scroll-to-checkout {
  display: none;
  width: 100%;
  background: #F43357;
  color: white;
  padding: 1rem 2rem;
  font-size: 1.125rem;
  font-weight: 600;
  border-radius: 9999px;
  text-decoration: none;
  text-align: center;
  margin-top: 1.5rem;
  box-shadow: 0 4px 12px rgba(244, 51, 87, 0.3);
  transition: all 0.3s ease;
}

#snooze-custom-checkout .mobile-scroll-to-checkout:hover {
  background: #e02d4f;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(244, 51, 87, 0.4);
}

@media (max-width: 768px) {
  #snooze-custom-checkout .snooze-checkout-hero h1 {
    font-size: 1.75rem;
  }

  #snooze-custom-checkout .snooze-checkout-hero .subheadline {
    font-size: 1rem;
  }

  #snooze-custom-checkout .trial-highlight,
  #snooze-custom-checkout .whats-included,
  #snooze-custom-checkout .how-it-works {
    padding: 1.5rem;
  }

  #snooze-custom-checkout .whats-included h2,
  #snooze-custom-checkout .how-it-works h2,
  #snooze-custom-checkout .why-join h2 {
    font-size: 1.5rem;
  }

  #snooze-custom-checkout .steps {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  #snooze-custom-checkout .mobile-scroll-to-checkout {
    display: block;
  }
}

@media (max-width: 360px) {
  .embedded-checkout-price-summary .offer-summary {
    display: grid !important;
    grid-template-columns: 4rem minmax(0, 1fr) !important;
    gap: 0.5rem !important;
  }

  .embedded-checkout-price-summary .offer-summary > div:first-child {
    width: 4rem !important;
  }

  .embedded-checkout-price-summary .offer-summary > pds-box:nth-of-type(1) {
    min-width: 0 !important;
  }

  .embedded-checkout-price-summary .offer-summary > pds-box:last-child {
    grid-column: 2;
    align-items: flex-start !important;
    min-width: 0 !important;
  }

  .embedded-checkout-price-summary .offer-summary > pds-box:last-child pds-text {
    text-align: left !important;
  }
}

settings.js:
(function() {
  'use strict';

  const PLAN_CONFIG = {
    USD: {
      offerCode: 'PUBMS02_USD',
      monthly: { variantId: '160544', plan: 'monthly', cadence: 'monthly', amount: 79 },
      quarterly: { variantId: '64815', plan: 'quarterly', cadence: 'every_3_months', amount: 198 },
      annual: { variantId: '64816', plan: 'annual', cadence: 'yearly', amount: 660 }
    },
    AUD: {
      offerCode: 'PUBMS02_AUD',
      monthly: { variantId: '160790', plan: 'monthly', cadence: 'monthly', amount: 119 },
      quarterly: { variantId: '160791', plan: 'quarterly', cadence: 'every_3_months', amount: 297 },
      annual: { variantId: '160792', plan: 'annual', cadence: 'yearly', amount: 996 }
    }
  };
  const ATTRIBUTION_KEYS = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'fbclid', 'gclid'];
  const OPTION_SELECTOR = '.embedded-checkout-pricing-option, [data-pricing-option-id], [data-variant-id]';
  const SELECTED_SELECTOR = '.embedded-checkout-pricing-option.selected, .embedded-checkout-pricing-option[aria-checked="true"], [data-pricing-option-id].selected, [data-pricing-option-id][aria-checked="true"], [data-variant-id].selected, [data-variant-id][aria-checked="true"]';
  let lastSelectionKey = '';

  function pushEvent(payload) {
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push(payload);
  }

  function checkoutContext() {
    const wrapper = document.getElementById('snooze-custom-checkout');
    if (!wrapper) return null;
    const currency = String(wrapper.getAttribute('data-currency') || '').toUpperCase();
    if (!PLAN_CONFIG[currency]) return null;
    return {
      wrapper: wrapper,
      currency: currency,
      offerId: String(wrapper.getAttribute('data-offer-id') || ''),
      offerCode: PLAN_CONFIG[currency].offerCode
    };
  }

  function optionText(option) {
    return String((option && (option.innerText || option.textContent)) || '').toLowerCase();
  }

  function optionVariantId(option) {
    if (!option) return '';
    const attributes = ['data-variant-id', 'data-pricing-option-id', 'data-variant', 'value'];
    for (let index = 0; index < attributes.length; index += 1) {
      const value = option.getAttribute && option.getAttribute(attributes[index]);
      if (value) return String(value);
    }
    const input = option.querySelector && option.querySelector('input[value], option[value]');
    return input && input.value ? String(input.value) : '';
  }

  function planFromOption(option, currency) {
    const plans = PLAN_CONFIG[currency];
    const variantId = optionVariantId(option);
    const keys = Object.keys(plans);
    for (let index = 0; index < keys.length; index += 1) {
      if (plans[keys[index]].variantId === variantId) return plans[keys[index]];
    }
    const text = optionText(option);
    if (text.indexOf('quarter') > -1 || text.indexOf('3 month') > -1) return plans.quarterly;
    if (text.indexOf('annual') > -1 || text.indexOf('year') > -1) return plans.annual;
    if (text.indexOf('month') > -1) return plans.monthly;
    return null;
  }

  function selectedOption() {
    const explicit = document.querySelector(SELECTED_SELECTOR);
    if (explicit) return explicit;
    const checked = document.querySelector('input:checked');
    return checked && checked.closest ? checked.closest(OPTION_SELECTOR) : null;
  }

  function syncSelection(emitEvent) {
    const context = checkoutContext();
    if (!context) return;
    const plan = planFromOption(selectedOption(), context.currency);
    if (!plan) return;
    const selectionKey = context.offerId + ':' + plan.variantId;
    if (emitEvent && lastSelectionKey && selectionKey !== lastSelectionKey) {
      pushEvent({
        event: 'pricing_option_selected',
        offer_id: context.offerId,
        offer_code: context.offerCode,
        variant_id: plan.variantId,
        plan: plan.plan,
        cadence: plan.cadence,
        amount: plan.amount,
        currency: context.currency,
        surface: 'trial_checkout'
      });
    }
    lastSelectionKey = selectionKey;
  }

  function preserveAttribution(link) {
    if (!link || !link.getAttribute) return;
    try {
      const destination = new URL(link.getAttribute('href'), window.location.origin);
      const current = new URL(window.location.href);
      ATTRIBUTION_KEYS.forEach(function(key) {
        if (!destination.searchParams.has(key) && current.searchParams.has(key)) {
          destination.searchParams.set(key, current.searchParams.get(key));
        }
      });
      link.setAttribute('href', destination.toString());
    } catch (error) {}
  }

  function isPricingOption(node) {
    return !!(node && node.nodeType === 1 && (
      (node.matches && node.matches(OPTION_SELECTOR)) ||
      (node.closest && node.closest(OPTION_SELECTOR))
    ));
  }

  function containsPricingOption(node) {
    return !!(node && node.nodeType === 1 && (
      isPricingOption(node) ||
      (node.querySelector && node.querySelector(OPTION_SELECTOR))
    ));
  }

  function mutationTouchesPricing(mutation) {
    if (!mutation) return false;
    if (mutation.type === 'attributes') return isPricingOption(mutation.target);
    if (mutation.type !== 'childList') return false;
    if (isPricingOption(mutation.target)) return true;
    const changedNodes = Array.prototype.slice.call(mutation.addedNodes || [])
      .concat(Array.prototype.slice.call(mutation.removedNodes || []));
    return changedNodes.some(containsPricingOption);
  }

  function scrollToCheckout(event) {
    if (event) event.preventDefault();
    const checkoutSelectors = [
      '.checkout-form', '.kajabi-checkout', '.checkout-container', '[data-checkout]',
      '.offer-checkout', '.checkout-wrapper', '.checkout-form-container',
      '.enhanced-checkout', '.checkout-right', '.checkout-sidebar',
      'form[action*="checkout"]', 'form[action*="offer"]'
    ];
    let checkoutElement = null;
    for (let index = 0; index < checkoutSelectors.length; index += 1) {
      checkoutElement = document.querySelector(checkoutSelectors[index]);
      if (checkoutElement) break;
    }
    if (checkoutElement) {
      checkoutElement.scrollIntoView({ behavior: 'smooth', block: 'start', inline: 'nearest' });
      window.setTimeout(function() {
        const firstInput = checkoutElement.querySelector('input, select, textarea, button');
        if (firstInput && firstInput.focus) firstInput.focus();
      }, 500);
      return;
    }
    const forms = document.querySelectorAll('form');
    if (forms.length > 0) {
      forms[forms.length - 1].scrollIntoView({ behavior: 'smooth', block: 'start' });
    } else {
      window.scrollTo({ top: document.documentElement.scrollHeight, behavior: 'smooth' });
    }
  }

  function init() {
    const context = checkoutContext();
    if (!context) return;
    const initialPlan = planFromOption(selectedOption(), context.currency) || PLAN_CONFIG[context.currency].monthly;

    if (!window.__snoozeTrialBeginCheckoutFired) {
      window.__snoozeTrialBeginCheckoutFired = true;
      pushEvent({
        event: 'begin_checkout',
        offer_id: context.offerId,
        offer_code: context.offerCode,
        currency: context.currency,
        value: initialPlan.amount,
        checkout_mode: '7_day_trial',
        surface: 'trial_checkout',
        ecommerce: {
          currency: context.currency,
          value: initialPlan.amount,
          items: [{
            item_id: context.offerCode,
            item_name: 'The Snooze Membership - 7 Day Trial',
            item_variant: initialPlan.plan,
            price: initialPlan.amount,
            quantity: 1
          }]
        }
      });
    }

    context.wrapper.querySelectorAll('.scroll-to-checkout, .mobile-scroll-to-checkout').forEach(function(button) {
      button.addEventListener('click', scrollToCheckout);
    });

    const currencyLink = context.wrapper.querySelector('[data-currency-switch]');
    preserveAttribution(currencyLink);
    if (currencyLink) {
      currencyLink.addEventListener('click', function() { preserveAttribution(currencyLink); }, true);
    }

    syncSelection(false);
    document.addEventListener('click', function(event) {
      if (event.target && event.target.closest && event.target.closest(OPTION_SELECTOR)) {
        window.setTimeout(function() { syncSelection(true); }, 0);
      }
    }, true);
    document.addEventListener('change', function(event) {
      if (event.target && event.target.closest && event.target.closest(OPTION_SELECTOR)) syncSelection(true);
    }, true);

    if (typeof MutationObserver !== 'undefined') {
      let syncScheduled = false;
      const observer = new MutationObserver(function(mutations) {
        if (!Array.prototype.some.call(mutations || [], mutationTouchesPricing) || syncScheduled) return;
        syncScheduled = true;
        window.setTimeout(function() {
          syncScheduled = false;
          syncSelection(true);
        }, 0);
      });
      observer.observe(document.body, { attributes: true, attributeFilter: ['class', 'aria-checked', 'checked'], childList: true, subtree: true });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
